"use client";

import * as React from "react";

import { Surface, type SurfaceProps } from "@lenso/ui/surface";

import {
  autosizePromptComposerInput,
  normalizePromptComposerMaxRows,
  observePromptComposerReflow,
} from "./autosize";
import { shouldSubmitPrompt, type PromptComposerSubmitShortcut } from "./keyboard";
import styles from "./prompt-composer.module.css";

interface PromptComposerContextValue {
  maxRows: number;
  onValueChange: (value: string) => void;
  submitShortcut: PromptComposerSubmitShortcut;
  value: string;
}

const PromptComposerContext = React.createContext<PromptComposerContextValue | null>(null);

function usePromptComposer(): PromptComposerContextValue {
  const context = React.useContext(PromptComposerContext);
  if (!context) {
    throw new Error("PromptComposer parts must be rendered inside PromptComposer.Root");
  }
  return context;
}

function mergeClassName(generated?: string, className?: string): string {
  return [generated, className].filter(Boolean).join(" ");
}

function assignRef<Value>(ref: React.ForwardedRef<Value>, value: Value | null): void {
  if (typeof ref === "function") {
    ref(value);
  } else if (ref) {
    ref.current = value;
  }
}

export interface PromptComposerRootProps extends Omit<
  React.ComponentPropsWithoutRef<"form">,
  "onChange"
> {
  maxRows?: number;
  onValueChange: (value: string) => void;
  surfaceClassName?: SurfaceProps["className"];
  submitShortcut?: PromptComposerSubmitShortcut;
  value: string;
}

export const PromptComposerRoot = React.forwardRef<HTMLFormElement, PromptComposerRootProps>(
  (
    {
      children,
      className,
      maxRows = 8,
      onValueChange,
      surfaceClassName,
      submitShortcut = "mod-enter",
      value,
      ...props
    },
    ref,
  ) => {
    const context = React.useMemo<PromptComposerContextValue>(
      () => ({
        maxRows: normalizePromptComposerMaxRows(maxRows),
        onValueChange,
        submitShortcut,
        value,
      }),
      [maxRows, onValueChange, submitShortcut, value],
    );

    return (
      <PromptComposerContext.Provider value={context}>
        <Surface className={mergeClassName(styles.surface, surfaceClassName)} level="panel">
          <form
            {...props}
            className={mergeClassName(styles.root, className)}
            data-slot="prompt-composer"
            ref={ref}
          >
            {children}
          </form>
        </Surface>
      </PromptComposerContext.Provider>
    );
  },
);
PromptComposerRoot.displayName = "PromptComposer.Root";

export interface PromptComposerInputProps extends Omit<
  React.ComponentPropsWithoutRef<"textarea">,
  "defaultValue" | "onChange" | "value"
> {
  onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
}

export const PromptComposerInput = React.forwardRef<HTMLTextAreaElement, PromptComposerInputProps>(
  ({ className, onChange, onKeyDown, rows = 1, ...props }, forwardedRef) => {
    const { maxRows, onValueChange, submitShortcut, value } = usePromptComposer();
    const textareaRef = React.useRef<HTMLTextAreaElement | null>(null);
    const resize = React.useCallback(() => {
      if (textareaRef.current) {
        autosizePromptComposerInput(textareaRef.current, maxRows);
      }
    }, [maxRows]);

    React.useLayoutEffect(resize, [resize, value]);

    React.useLayoutEffect(() => {
      const textarea = textareaRef.current;
      if (!textarea) {
        return;
      }

      return observePromptComposerReflow(textarea, resize);
    }, [resize]);

    return (
      <textarea
        {...props}
        className={mergeClassName(styles.input, className)}
        data-slot="prompt-composer-input"
        onChange={(event) => {
          onValueChange(event.currentTarget.value);
          onChange?.(event);
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          if (event.defaultPrevented) {
            return;
          }

          if (
            shouldSubmitPrompt(
              {
                altKey: event.altKey,
                ctrlKey: event.ctrlKey,
                isComposing: event.nativeEvent.isComposing,
                key: event.key,
                metaKey: event.metaKey,
                shiftKey: event.shiftKey,
              },
              submitShortcut,
            )
          ) {
            event.preventDefault();
            event.currentTarget.form?.requestSubmit();
          }
        }}
        ref={(node) => {
          textareaRef.current = node;
          assignRef(forwardedRef, node);
        }}
        rows={rows}
        value={value}
      />
    );
  },
);
PromptComposerInput.displayName = "PromptComposer.Input";

export type PromptComposerToolbarProps = React.ComponentPropsWithoutRef<"div">;

export const PromptComposerToolbar = React.forwardRef<HTMLDivElement, PromptComposerToolbarProps>(
  ({ className, ...props }, ref) => (
    <div
      {...props}
      className={mergeClassName(styles.toolbar, className)}
      data-slot="prompt-composer-toolbar"
      ref={ref}
    />
  ),
);
PromptComposerToolbar.displayName = "PromptComposer.Toolbar";

export type PromptComposerActionsProps = React.ComponentPropsWithoutRef<"div">;

export const PromptComposerActions = React.forwardRef<HTMLDivElement, PromptComposerActionsProps>(
  ({ className, ...props }, ref) => (
    <div
      {...props}
      className={mergeClassName(styles.actions, className)}
      data-slot="prompt-composer-actions"
      ref={ref}
    />
  ),
);
PromptComposerActions.displayName = "PromptComposer.Actions";

export const PromptComposer = {
  Actions: PromptComposerActions,
  Input: PromptComposerInput,
  Root: PromptComposerRoot,
  Toolbar: PromptComposerToolbar,
} as const;

export type { PromptComposerSubmitShortcut } from "./keyboard";

export function normalizePromptComposerMaxRows(value: number): number {
  return Number.isFinite(value) ? Math.max(1, Math.floor(value)) : 8;
}

function numberFromCss(value: string): number {
  const parsed = Number(value.endsWith("px") ? value.slice(0, -2) : value);
  return Number.isFinite(parsed) ? parsed : 0;
}

export function autosizePromptComposerInput(textarea: HTMLTextAreaElement, maxRows: number): void {
  const computed = window.getComputedStyle(textarea);
  const fontSize = numberFromCss(computed.fontSize);
  const lineHeight = numberFromCss(computed.lineHeight) || fontSize * 1.5;
  const padding =
    numberFromCss(computed.paddingBlockStart) + numberFromCss(computed.paddingBlockEnd);
  const border =
    numberFromCss(computed.borderBlockStartWidth) + numberFromCss(computed.borderBlockEndWidth);
  const maximumHeight = lineHeight * normalizePromptComposerMaxRows(maxRows) + padding + border;

  textarea.style.height = "auto";
  const contentHeight = textarea.scrollHeight + border;
  textarea.style.height = `${Math.min(contentHeight, maximumHeight)}px`;
  textarea.style.overflowY = contentHeight > maximumHeight ? "auto" : "hidden";
}

function reflowSignature(textarea: HTMLTextAreaElement): string {
  const computed = window.getComputedStyle(textarea);
  return [
    textarea.getBoundingClientRect().width,
    computed.fontFamily,
    computed.fontSize,
    computed.lineHeight,
    computed.paddingBlockStart,
    computed.paddingBlockEnd,
  ].join(":");
}

export function observePromptComposerReflow(
  textarea: HTMLTextAreaElement,
  onReflow: () => void,
): () => void {
  let signature = reflowSignature(textarea);
  const handleReflow = () => {
    const nextSignature = reflowSignature(textarea);
    if (nextSignature === signature) {
      return;
    }
    signature = nextSignature;
    onReflow();
  };

  if (typeof ResizeObserver === "undefined") {
    window.addEventListener("resize", handleReflow);
    return () => window.removeEventListener("resize", handleReflow);
  }

  const observer = new ResizeObserver(handleReflow);
  observer.observe(textarea);
  return () => observer.disconnect();
}

export type PromptComposerSubmitShortcut = "enter" | "mod-enter" | "none";

export interface PromptComposerKeyGesture {
  altKey: boolean;
  ctrlKey: boolean;
  isComposing: boolean;
  key: string;
  metaKey: boolean;
  shiftKey: boolean;
}

export function shouldSubmitPrompt(
  gesture: PromptComposerKeyGesture,
  shortcut: PromptComposerSubmitShortcut,
): boolean {
  if (
    shortcut === "none" ||
    gesture.key !== "Enter" ||
    gesture.isComposing ||
    gesture.altKey ||
    gesture.shiftKey
  ) {
    return false;
  }

  const hasModifier = gesture.metaKey || gesture.ctrlKey;
  return shortcut === "mod-enter" ? hasModifier : !hasModifier;
}

.surface {
  width: 100%;
  overflow: hidden;
  padding: 0;
}

.root {
  display: grid;
  box-sizing: border-box;
  gap: var(--space-2, 8px);
  width: 100%;
  min-width: 0;
  padding: var(--space-3, 12px);
}

.input {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  margin: 0;
  padding: 0;
  resize: none;
  border: 0;
  outline: none;
  background: transparent;
  color: var(--color-content-primary);
  font: inherit;
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  overflow-wrap: anywhere;
}

.input::placeholder {
  color: var(--color-content-tertiary);
  opacity: 1;
}

.input:focus-visible {
  outline: 2px solid var(--color-focus-ring);
  outline-offset: 3px;
}

.toolbar,
.actions {
  display: flex;
  align-items: center;
}

.toolbar {
  justify-content: space-between;
  gap: var(--space-2, 8px);
  min-width: 0;
}

.actions {
  gap: var(--space-1, 4px);
}

@media (forced-colors: active) {
  .surface {
    border: 1px solid CanvasText;
  }

  .input:focus-visible {
    outline-color: Highlight;
  }
}
